UPDATE posts SET seo = jsonb_set(COALESCE(seo, '{}'), '{schema}', '{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Which is cheaper, Notion or Coda?","acceptedAnswer":{"@type":"Answer","text":"Notion offers a generous free plan for individuals. Coda is also free for small docs. Notion Pro costs $10/month vs Coda Pro at $10/month. For solo freelancers, both free tiers are sufficient."}},{"@type":"Question","name":"Is there a free version of Notion and Coda?","acceptedAnswer":{"@type":"Answer","text":"Yes, both offer free plans. Notion Free includes unlimited pages with a 5 MB upload limit. Coda Free includes unlimited docs with a row limit. For most freelancers, the free tiers cover daily needs."}},{"@type":"Question","name":"Which is better for a freelancer, Notion or Coda?","acceptedAnswer":{"@type":"Answer","text":"Notion excels at knowledge management and clean documentation. Coda is stronger for spreadsheet-like automations and interactive docs. If you need a simple wiki and project tracker, choose Notion. If you need calculated tables and buttons, choose Coda."}}]}'::jsonb) WHERE id = 48;

UPDATE posts SET seo = jsonb_set(COALESCE(seo, '{}'), '{schema}', '{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Which is cheaper, ChatGPT or Claude?","acceptedAnswer":{"@type":"Answer","text":"ChatGPT Plus costs $20/month. Claude Pro also costs $20/month. Both offer free tiers with usage limits. For light usage, the free versions are sufficient; for heavy daily use, the paid plans are equivalent in price."}},{"@type":"Question","name":"Which AI is better for coding, ChatGPT or Claude?","acceptedAnswer":{"@type":"Answer","text":"Claude tends to produce longer, more structured code with fewer hallucinations. ChatGPT is faster for quick snippets and has a broader plugin ecosystem. For full-stack development, Claude is often preferred; for rapid prototyping, ChatGPT works well."}},{"@type":"Question","name":"Is there a free version of ChatGPT and Claude?","acceptedAnswer":{"@type":"Answer","text":"Yes, both offer free tiers. ChatGPT Free uses GPT-4o-mini with daily limits. Claude Free provides access to Claude Sonnet with message caps. Both are usable for occasional tasks but insufficient for professional daily use."}}]}'::jsonb) WHERE id = 49;

UPDATE posts SET seo = jsonb_set(COALESCE(seo, '{}'), '{schema}', '{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Which is cheaper, Zapier or Make?","acceptedAnswer":{"@type":"Answer","text":"Make is significantly cheaper. Its free plan includes 1,000 operations/month vs Zapier free at 100 tasks/month. Make Pro starts at $9/month for 10,000 operations, while Zapier Starter costs $19.99/month for 750 tasks."}},{"@type":"Question","name":"Is Make really better than Zapier for freelancers?","acceptedAnswer":{"@type":"Answer","text":"For budget-conscious freelancers, Make offers far better value with more operations per dollar. Zapier is easier to set up with simpler workflows. If you need complex multi-step automations on a budget, Make wins."}},{"@type":"Question","name":"Is there a free version of Zapier and Make?","acceptedAnswer":{"@type":"Answer","text":"Yes, both have free plans. Zapier Free allows 100 tasks/month with single-step zaps. Make Free provides 1,000 operations/month with multi-step scenarios. Make free tier is 10x more generous."}}]}'::jsonb) WHERE id = 50;

UPDATE posts SET seo = jsonb_set(COALESCE(seo, '{}'), '{schema}', '{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Which is cheaper, Figma or Canva?","acceptedAnswer":{"@type":"Answer","text":"Canva Pro costs $12.99/month. Figma Professional costs $15/month per editor. Canva Free is very generous for non-designers. For freelancers doing marketing visuals, Canva is cheaper; for UI/UX design, Figma is the industry standard."}},{"@type":"Question","name":"Can Canva replace Figma for a freelancer?","acceptedAnswer":{"@type":"Answer","text":"It depends on your work. Canva excels at social media graphics, presentations, and marketing materials. Figma is built for interface design, prototyping, and developer handoff. If you design apps or websites, Figma cannot be replaced by Canva."}},{"@type":"Question","name":"Is there a free version of Figma and Canva?","acceptedAnswer":{"@type":"Answer","text":"Yes, both offer free plans. Canva Free includes thousands of templates and basic design tools. Figma Free allows 3 files with full editing capabilities. For solo freelancers starting out, both free tiers are workable."}}]}'::jsonb) WHERE id = 51;

UPDATE posts SET seo = jsonb_set(COALESCE(seo, '{}'), '{schema}', '{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Which is cheaper, Slack or Microsoft Teams?","acceptedAnswer":{"@type":"Answer","text":"Microsoft Teams is free with a Microsoft 365 subscription ($6/month). Slack Pro costs $8.75/month per user. For freelancers already paying for Microsoft 365, Teams is essentially free."}},{"@type":"Question","name":"Is Slack worth paying for as a freelancer?","acceptedAnswer":{"@type":"Answer","text":"For most solo freelancers, Slack Free is sufficient with 90 days of message history. Paying for Slack Pro is only worth it if you need full message history and advanced integrations."}},{"@type":"Question","name":"Is there a free version of Slack and Teams?","acceptedAnswer":{"@type":"Answer","text":"Yes, both have free tiers. Slack Free includes 90 days of message history and 10 app integrations. Teams Free includes chat, video calls, and 5 GB of storage. Both are usable for small teams and freelancers."}}]}'::jsonb) WHERE id = 52;